function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"El taller presencial de tres horas: 1.500 lempiras por sesión. Es lo que más rápido se cobra y lo que más dinero deja hoy."},{"txt":"El mismo taller en paquete, con las hojas listas, la guía del facilitador y un precio cerrado por centro."},{"txt":"El cuaderno impreso de fichas: ochenta páginas, se vende por centro o por maestra, y lleva cuatro meses al ochenta por ciento."},{"txt":"La licencia anual de la aplicación por centro: pagan una vez al año y sus maestras la usan todo el curso."},{"txt":"Una asesoría mensual «ilimitada» a un centro: cantidad fija cada mes y disponibilidad para lo que haga falta."},{"txt":"Un curso grabado que se vendió como producto, y cada compra trae dudas por mensaje durante semanas."},{"txt":"Un centro paga bien y por adelantado por un material, y el contrato dice en una línea que la autoría queda a su nombre."},{"txt":"Una ficha suelta buena, gratis y descargable por cualquiera. No deja un lempira y se descarga mucho."}];
const critCaseQuestions=["1. ¿En qué escalón está, y cobra si te vas dos semanas?","2. ¿Qué se haría UNA sola vez para subir el escalón siguiente?","3. ¿Cuántas horas al mes pide de mantenimiento?","4. Escribe en 3-4 frases a nombre de quién queda y dónde está escrito eso."];
const critCaseGuides=["Se nombra el escalón (hora, paquete, producto o sistema) y se contesta con un sí o un no, sin medias tintas: solo el producto y el sistema cobran estando fuera.","Tiene que ser algo que se hace una vez: guardar el material, escribir la guía, grabar, convertir las dudas repetidas en una hoja. Si hay que repetirlo cada vez, no sube ningún escalón.","En horas, no en ganas. Si pide más horas de las que deja, es una afición cara. Y si son cero, hay que mirarlo otra vez, porque ningún activo cuesta cero.","A nombre de quién queda, y en qué papel está escrito. Si la respuesta es «no lo sé», ese es el trabajo pendiente, y se hace antes de firmar y no después."];

const critErrorBank=[{"txt":"\"Este mes gané más que nunca, vamos bien\".","g1":"El total no mide esta etapa. Lo que mide es cuánto entró sin haber trabajado ese mes, que puede ser cero en el mejor mes del año.","g2":"Ganar más dando más talleres es seguir en el primer escalón, mejor pagado y con menos tiempo para construir el segundo."},{"txt":"\"Voy a dejar el trabajo para dedicarme a esto a tiempo completo\".","g1":"Es la peor situación posible para construir: hay que cobrar rápido, y cobrar rápido significa vender horas, que es el escalón del que se quería salir.","g2":"El sueldo compra lo único que hace falta, que es tiempo sin urgencia. Con dos horas semanales un cuaderno de ochenta páginas se termina en un año."},{"txt":"\"El curso está grabado, ya es un producto\".","g1":"Si cada compra trae dudas por mensaje, se cobró como producto y cuesta como empleo. Y empeora con el éxito: vender más es trabajar más.","g2":"Se arregla una vez: las dudas repetidas se convierten en material añadido y las que no se repiten se cobran como asesoría."},{"txt":"\"Pagan muy bien, no importa a nombre de quién quede\".","g1":"Importa, y es lo único que importa a cinco años vista. El material va a producir todos los cursos, para quien tenga el papel.","g2":"La contraoferta casi siempre se acepta: «el material es mío y ustedes tienen licencia de uso ilimitada dentro del centro». Lo que querían era usarlo."},{"txt":"\"La aplicación no me cuesta nada mantenerla\".","g1":"Ningún activo cuesta cero. Si de verdad no pide nada, o está muerto o el costo lo está pagando alguien sin decirlo.","g2":"Se cuentan las horas de un mes normal: arreglos, copias de seguridad, dudas. Con ese número ya se puede decidir si sigue o no."},{"txt":"\"Regalo esta ficha para que me conozcan\".","g1":"Una ficha gratis está bien, pero es una puerta y se juzga como puerta: por cuánta gente trae, no por lo que deja.","g2":"Y para que sea puerta tiene que llevar dentro el nombre, el código y a dónde ir después. Sin eso es trabajo regalado."}];

const critDecisionBank=["El único sábado libre del mes: ¿taller de 1.500 lempiras o terminar el cuaderno que lleva cuatro meses al ochenta por ciento?","Un centro pide asesoría mensual ilimitada por una cantidad fija: ¿se acepta, se rechaza o se replantea?","El curso grabado trae dudas cada semana: ¿se contesta, se deja de contestar o se cambia algo de una vez?","Un contrato bueno con una línea que cede la autoría: ¿se firma, se rechaza o se contraoferta?","La aplicación pide arreglos cada semana y deja poco: ¿se sostiene, se sube el precio o se cierra?","Cinco talleres dados y ningún material guardado: ¿qué se hace antes del sexto?","Una ficha gratis que se descarga mucho y no trae contactos: ¿se deja de hacer o se le cambia algo?","Hay dos horas libres el domingo: ¿se preparan dos talleres nuevos o se avanza el producto?"];
const critDecisionGuide="La decisión correcta sigue las reglas de la casa: si el ingreso se para cuando tú te paras es un empleo, aunque sea tuyo, así que lo primero es decir en qué escalón está la cosa: hora, paquete, producto o sistema. Nada nace activo, y no se salta ningún escalón: se sube con lo que ya se está haciendo, haciendo una sola vez lo que se venía haciendo cada vez. El activo se construye con el sueldo y no en lugar del sueldo, porque el sueldo compra lo único que hace falta, que es tiempo sin urgencia. Todo activo pide mantenimiento y se cuenta en horas al mes: si pide más de lo que deja, es una afición cara. Y la pregunta final no es cuánto deja, sino a nombre de quién queda y dónde está escrito eso, que se pregunta antes de firmar y no después.";

const critCompareBank=[{"a":"Dar el taller del sábado por 1.500 lempiras.","b":"Terminar el cuaderno que lleva cuatro meses al ochenta por ciento.","ga":"Caso A: entra dinero seguro hoy y las cuentas se pagan. Es la decisión correcta si ese dinero hace falta este mes de verdad.","gb":"Caso B: cero lempiras hoy y un producto que se vende muchas veces después. Y hay un dato que decide: llevas seis meses eligiendo A, y el cuaderno lleva seis meses al ochenta por ciento."},{"a":"Cobrar por hora, con precio alto.","b":"Cobrar un paquete cerrado con material y guía.","ga":"Caso A: el precio sube pero el techo es el mismo, porque las horas del día no crecen. Y sigue sin cobrar el mes que faltes.","gb":"Caso B: el mismo trabajo y más dinero, porque el centro recibe más cosas; y sobre todo, el molde queda hecho para el siguiente."},{"a":"Aceptar el contrato que cede la autoría, que paga bien.","b":"Contraofertar licencia de uso ilimitada dentro del centro.","ga":"Caso A: entra dinero ahora y el material produce cada curso para el centro, no para ti. Se cobró una vez lo que iba a valer años.","gb":"Caso B: cuesta lo mismo para ellos y resuelve su necesidad entera. Casi siempre se acepta, porque lo que querían era usarlo, no venderlo."},{"a":"Contestar cada duda del curso grabado, una por una.","b":"Convertir las dudas repetidas en material añadido.","ga":"Caso A: el comprador queda contento y el trabajo semanal no baja nunca; al contrario, sube con cada venta nueva.","gb":"Caso B: cuesta un fin de semana una sola vez y baja el mantenimiento de horas semanales a horas anuales."}];

const critCauseBank=[{"cause":"Todo el ingreso está en el primer escalón.","guide":"Cualquier semana de enfermedad se convierte en un mes sin dinero. Y como no hay margen, no hay horas para construir el segundo escalón: el trabajo se come a sí mismo."},{"cause":"Se vende una asesoría sin número de horas.","guide":"Crece hasta ocupar todo el mes sin que nadie lo decida, porque el centro pide lo que necesita y tú aceptas lo que puedes. Acaba siendo un empleo sin prestaciones."},{"cause":"Se cobra como producto algo que exige atención semanal.","guide":"El éxito se vuelve castigo: cada venta añade trabajo fijo. Es el único caso donde vender más empeora la situación de quien vende."},{"cause":"Se firma un contrato sin mirar a nombre de quién queda el material.","guide":"El material produce cada curso, para el centro. Se cobró una vez lo que iba a valer durante años, y esa línea no se puede renegociar después."},{"cause":"No se cuenta el mantenimiento en horas.","guide":"Se sostienen cosas que cuestan más de lo que dejan, y se sostienen por cariño. Con el número delante la decisión se toma en dos minutos."},{"cause":"Se regalan fichas sin nombre, código ni contacto.","guide":"Se descargan mucho y no traen a nadie. Eso no es una puerta: es trabajo regalado, y de eso ya hay bastante en este oficio."}];
const critEffectBank=[{"effect":"Preparar el sexto taller costó media hora en vez de seis.","guide":"Se guardó el material de los cinco anteriores en una carpeta con fecha. El molde se construyó sin dedicarle una sola hora extra."},{"effect":"Entró dinero el mes que estuvo enfermo.","guide":"Había algo en el tercer escalón: un producto terminado que alguien podía entregar sin él."},{"effect":"El mantenimiento del curso bajó de horas semanales a horas anuales.","guide":"Las dudas repetidas se convirtieron en material añadido y las que no se repetían pasaron a cobrarse como asesoría."},{"effect":"El material sigue produciendo y es suyo.","guide":"Se contraofertó licencia de uso ilimitada dentro del centro en vez de ceder la autoría, y el centro aceptó sin discutir."},{"effect":"Se cerró una aplicación sin remordimiento.","guide":"Se contaron las horas de mantenimiento de un mes normal y se compararon con lo que dejaba. Con el número delante no hubo debate."},{"effect":"Una ficha gratis trajo once contactos en un mes.","guide":"Llevaba dentro el nombre, el código y a dónde ir después. Era una puerta, no trabajo regalado."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🧠 El escalón siguiente · Forma ${cf} · Del salario al activo · Ruta del Poder`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. El ingreso sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿En qué escalón está este ingreso, qué se haría una sola vez para subir el siguiente y cuántas horas al mes pide de mantenimiento? Explica por qué eso es mejor que cobrar más por hora o que aceptar más trabajo del mismo.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos sigue cobrando el mes que te enfermes? 2. ¿Por qué no son la misma decisión, aunque este mes dejen lo mismo?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0–20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 El escalón siguiente: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. El ingreso sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿En qué escalón está este ingreso, qué se haría una sola vez para subir el siguiente y cuántas horas al mes pide de mantenimiento? Explica por qué eso es mejor que cobrar más por hora o que aceptar más trabajo del mismo.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos sigue cobrando el mes que te enfermes? 2. ¿Por qué no son la misma decisión, aunque este mes dejen lo mismo?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>El escalón siguiente Del salario al activo · Ruta del Poder · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #3b3a86;background:#ece9fb;color:#3b3a86;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#3b3a86;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #3b3a86;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#ece9fb;border-left:3px solid #3b3a86;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#ece9fb;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#ece9fb;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#3b3a86;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #3b3a86;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · El escalón siguiente · Del salario al activo · Ruta del Poder · Etapa 4 · Poder Económico</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: El escalón siguiente · Del salario al activo · Ruta del Poder · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1","icon":"🧱","label":"El molde","text":"Lo que se hace <strong>una vez</strong> para no volver a hacerlo. <strong>Si falta:</strong> cada venta cuesta lo mismo que la primera. <strong>En M.E.T.A.S:</strong> la guía del taller y las hojas preparadas."},{"y":"2","icon":"🔁","label":"La copia","text":"Que se pueda entregar otra vez <strong>sin volver a fabricarlo</strong>. <strong>Si falta:</strong> hay molde pero no hay activo. <strong>En M.E.T.A.S:</strong> el cuaderno impreso y el material descargable."},{"y":"3","icon":"💵","label":"El cobro","text":"Que alguien pague, y <strong>por dónde paga</strong>. <strong>Si falta:</strong> es un buen material que no da de comer. <strong>En M.E.T.A.S:</strong> por centro, por maestra o por licencia anual."},{"y":"4","icon":"🚪","label":"La puerta","text":"Lo que se regala para <strong>traer gente</strong> a lo que cobra. <strong>Si falta:</strong> el producto no se vende solo. <strong>En M.E.T.A.S:</strong> la ficha gratis con código y teléfono."},{"y":"5","icon":"🔧","label":"El mantenimiento","text":"Las <strong>horas al mes</strong> que pide para seguir vivo. <strong>Si es más de lo que deja:</strong> es una afición cara. <strong>En M.E.T.A.S:</strong> erratas, reimpresiones y copias de seguridad."},{"y":"6","icon":"📜","label":"La propiedad","text":"<strong>A nombre de quién queda</strong> lo que produce. <strong>Si falta:</strong> el activo es de otro y produce para otro. <strong>En M.E.T.A.S:</strong> nombre impreso dentro, no solo en la portada."},{"y":"7","icon":"🤝","label":"El relevo","text":"Qué pasa <strong>si te enfermas un mes</strong>. <strong>Si la respuesta es «se para»:</strong> el activo eres tú. <strong>En M.E.T.A.S:</strong> guía escrita para que otro pueda dar el taller."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(terminaElCuaderno){sfx(terminaElCuaderno?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(terminaElCuaderno){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🧱</span><span class="ms-text"><strong>Ese sábado entraron 0 lempiras</strong> y el cuaderno quedó terminado. La semana siguiente fue a la imprenta un lote de cincuenta.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✅</span><span class="ms-text"><strong>Cuatro meses después:</strong> el cuaderno dejó más que tres talleres, y el mes que estuviste con gripe siguió entrando dinero. El taller se puede seguir dando; el cuaderno ya no hay que volver a hacerlo.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">💵</span><span class="ms-text"><strong>Entraron 1.500 lempiras</strong> y estuvieron muy bien: pagaron la fotocopiadora del mes. La decisión no fue mala.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">7</span><span class="ms-icon">📉</span><span class="ms-text"><strong>Pero es la séptima vez:</strong> el cuaderno sigue al ochenta por ciento y el mes que viene el sábado libre traerá la misma oferta. Siete sábados son 10.500 lempiras y un producto sin terminar.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"molde":{"nombre":"El molde","icon":"🧱","estructura":{"title":"Qué es","info":"• Lo que se hace <strong>una sola vez</strong> para no repetirlo<br>• La guía, las hojas preparadas, el archivo que se copia<br>• Sin molde no se sube ningún escalón"},"funcion":{"title":"Cómo se construye","info":"• Con lo que ya se está haciendo: <strong>guardar el material de cada vez</strong><br>• Con fecha, en una carpeta, aunque esté a medias<br>• A la quinta vez el paquete ya está armado"},"enfermedades":{"title":"Qué pasa si falta","info":"• Cada venta cuesta lo mismo que la primera<br>• Y a los cinco años se sigue empezando de cero cada vez<br>• El precio por hora sube y el techo no se mueve"},"cuidados":{"title":"En M.E.T.A.S","info":"• Las fichas son el molde: <strong>se hicieron una vez</strong><br>• El molde de misión de la aplicación es otro, y por eso cada etapa nueva cuesta menos<br>• Lo que falta es el molde del taller: la guía escrita"}},"copia":{"nombre":"La copia","icon":"🔁","estructura":{"title":"Qué es","info":"• Que se pueda entregar otra vez <strong>sin volver a fabricarlo</strong><br>• Es lo que separa el molde del activo<br>• Un cuaderno se copia; una clase particular no"},"funcion":{"title":"Cómo se construye","info":"• Poniendo el trabajo en un soporte que se reproduce<br>• Papel, archivo, grabación, aplicación<br>• Y comprobando que <strong>funcione sin ti delante</strong>"},"enfermedades":{"title":"Qué pasa si falta","info":"• Hay molde pero no hay activo: el trabajo está hecho y no se puede vender dos veces<br>• Se acumulan carpetas de material que nadie usa<br>• Y se sigue cobrando por hora"},"cuidados":{"title":"En M.E.T.A.S","info":"• El cuaderno impreso se copia en la fotocopiadora<br>• La aplicación se copia sola: <strong>una vez escrita, sirve a todos</strong><br>• El taller presencial no se copia, y por eso hay que grabarlo"}},"cobro":{"nombre":"El cobro","icon":"💵","estructura":{"title":"Qué es","info":"• Que alguien pague, y <strong>por dónde paga</strong><br>• Precio, forma de cobro y quién entrega<br>• Un activo sin cobro es un buen material que no da de comer"},"funcion":{"title":"Cómo se construye","info":"• Precio decidido en frío, con la etapa 2 de esta ruta delante<br>• Una manera concreta de pagar, no «ya veremos»<br>• Y alguien que pueda entregar si tú no estás"},"enfermedades":{"title":"Qué pasa si falta","info":"• Se regala lo que costó meses<br>• O se cobra tan tarde que da igual haber cobrado<br>• Y se confunde interés con venta: <strong>preguntar no es pagar</strong>"},"cuidados":{"title":"En M.E.T.A.S","info":"• Por centro, por maestra o por <strong>licencia anual</strong><br>• El precio se pone antes, no cuando llaman<br>• Y la ficha gratis es puerta, no producto"}},"relevo":{"nombre":"El relevo","icon":"🤝","estructura":{"title":"Qué es","info":"• Qué pasa con esto <strong>si te enfermas un mes</strong><br>• Es la prueba final de toda la etapa<br>• Si la respuesta es «se para», el activo eres tú"},"funcion":{"title":"Cómo se construye","info":"• Escribiendo la guía para que <strong>lo pueda dar otra persona</strong><br>• Dejando el material donde alguien más lo encuentre<br>• Y probándolo una vez de verdad, no en teoría"},"enfermedades":{"title":"Qué pasa si falta","info":"• Descansar cuesta dinero, que es la señal de alarma de la etapa<br>• Y el proyecto entero depende de que una persona no se enferme<br>• Que es una manera cara de vivir"},"cuidados":{"title":"En M.E.T.A.S","info":"• Las fichas ya tienen relevo: <strong>funcionan sin nadie delante</strong><br>• El taller todavía no, y por eso hace falta la guía<br>• Y las llaves de la aplicación se guardan como enseña la Casa Cerrada"}}};
let labParte='molde',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue contando lo que entra sin ti!','¡Muy buen trabajo!','¡Ya distingues el activo del empleo!','¡Construyes molde cada semana!','¡Preguntas a nombre de quién queda!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🌱 ¡'+name+' completó la Etapa 4 de la Ruta del Poder (Del salario al activo)! 🏅 Progreso: '+pct+'% · ⚙️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

